"""Maximum punishments under the Indian Penal Code, 1860 (repealed 1 July 2024, but offences committed before that
date are still tried under it - which is most of the undertrial population today).

Same field conventions as punishments_bns.py. Coverage: the sections that account for the bulk of undertrials
(NCRB Prison Statistics: offences against body, property, women; rioting; cheating; forgery) plus the common
procedural companions. Unlisted sections resolve as UNKNOWN_SECTION and the engine refuses to assess them.
"""

P = {}

def _(key, max_years=None, *, min_years=0, life=False, death=False, life_if=None, fine_only=False, umbrella=False,
      variants=None, notes=""):
    P[key] = dict(max_years=max_years, min_years=min_years, life=life, death=death, life_if=life_if, fine_only=fine_only,
                  umbrella=umbrella, variants=variants or [], notes=notes)

