_("120B(2)", 0.5, notes="Criminal conspiracy to commit any other offence: up to 6 months, or fine, or both.")
_("120B", umbrella=True, variants=["120B(1)", "120B(2)"], notes="Specify the principal offence.")
_("511", None, notes="Attempt: up to one-half of life (read as 10 years) or one-half of the longest term - resolve against the principal offence.")
